export const mapZodParser = (schema: MapSchema, options: ZodParserOptions = {}): z.ZodTypeAny => {
  const { mode = 'put' } = options

  const displayedAttrEntries =
    mode === 'key'
      ? Object.entries(schema.attributes).filter(([, { props }]) => props.key)
      : Object.entries(schema.attributes)

  return withAttributeNameEncoding(
    schema,
    options,
    withDefault(
      schema,
      options,
      withOptional(
        schema,
        options,
        withValidate(
          schema,
          z.object(
            Object.fromEntries(
              displayedAttrEntries.map(([attributeName, attribute]) => [
                attributeName,
                schemaZodParser(attribute, { ...options, defined: false })
              ])
            )
          )
        ).superRefine((value, ctx) => {
          for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
            if (attribute.props.required === 'always' || value[attributeName] !== undefined)
              continue
            for (const requiredIf of attribute.props.requiredIf ?? []) {
              if (
                value[requiredIf.attributeName] !== undefined &&
                requiredIf.values.some(trigger =>
                  Object.is(trigger, value[requiredIf.attributeName])
                )
              ) {
                ctx.addIssue({
                  code: z.ZodIssueCode.custom,
                  path: [attributeName],
                  message: `Required when '${requiredIf.attributeName}' matches a requiredIf trigger.`
                })
              }
            }
          }
        })
      )
    )
  )
}

